import data from "./photo-credits.json";

/**
 * Photography attribution. The JSON is generated by
 * `scripts/download-images.mjs` whenever imagery is refreshed.
 */
export type PhotoCredit = {
  file: string;
  title: string;
  artist: string;
  license: string;
  source: string;
};

export const photoCredits: PhotoCredit[] = data;
